   const surface=await getRenderedSurface();if(ticket!==sequence)return;const laneRings=drapeReviewRings(buildLaneReview(roads),surface);laneReview.add(new Graphic({geometry:{type:'polygon',rings:laneRings,hasZ:true,spatialReference:{wkid:4326}},symbol:{type:'polygon-3d',symbolLayers:[{type:'fill',material:{color:'#e9ca73'}}]},popupTemplate:{title:'雙黃線街景樣式核對',content:'樣式依 2025 年 1 月松智路街景。定位依 OSM 中心線；線寬與間隔未量測，非精確現況標線圖。'}}));
   const junction=buildJunctionReview(roads);for(const [kind,rings] of Object.entries(junction)){const draped=drapeReviewRings(rings,surface);if(!draped.length)continue;junctionReview.add(new Graphic({geometry:{type:'polygon',rings:draped,hasZ:true,spatialReference:{wkid:4326}},symbol:{type:'polygon-3d',symbolLayers:[{type:'fill',material:{color:'#f1efdf'}}]},attributes:{kind:{dashes:'白色虛線',arrows:'導向箭頭',stop:'停止線'}[kind]},popupTemplate:{title:'路口標線核對樣板・{kind}',content:'樣式依 2025 年 1 月街景，定位與尺寸尚未量測。不是精確現況標線圖。'}}));}$('junctionReviewView').disabled=false;const waiting=buildWaitingReview(roads);for(const [kind,rings] of Object.entries(waiting)){const draped=drapeReviewRings(rings,surface);if(!draped.length)continue;for(const ring of draped)(kind==='grid'?gridReview:waitingReview).add(new Graphic({geometry:{type:'polygon',rings:[kind==='grid'?ring:ring.map(p=>p.slice(0,2))],hasZ:kind==='grid',spatialReference:{wkid:4326}},symbol:{type:'polygon-3d',symbolLayers:[{type:'fill',material:{color:'#f1efdf'}}]},attributes:{kind:kind==='motorcycle'?'機車停等框':'斜向網格'},popupTemplate:{title:'待驗證樣板・{kind}',content:'定位、尺寸及網格種類未完成現況驗證。'}}));}$('waitingReviewView').disabled=false;$('paintReviewView').disabled=false;
