   for(const f of data.lamps){const attrs={sourceId:f.id,note:f.heightVerified?'位置及桿高依市府資料；燈具造型待核對':'位置依市府資料；桿高與燈具造型為示意'};const base={longitude:f.lon,latitude:f.lat,spatialReference:{wkid:4326}};fixtures.add(new Graphic({geometry:new Point({...base,z:0}),symbol:object('cylinder','#6e7477',.16,.16,f.height),attributes:attrs,popupTemplate:{title:'市府路燈 {sourceId}',content:'{note}'}}));fixtures.add(new Graphic({geometry:new Point({...base,z:f.height}),symbol:object('cube','#d9dedc',.5,.3,.2),attributes:attrs,popupTemplate:{title:'路燈示意燈具',content:'{note}'}}));}
