   for(const f of verified.poles)signalPoles.add(new Graphic({geometry:new Point({longitude:f.lon,latitude:f.lat,z:0,spatialReference:{wkid:4326}}),symbol:object('cylinder','#9ba5a7',.12,.12,3),attributes:{sourceId:String(f.id),note:'位置依市府人行道桿類設施・號誌分類；桿高 3 m、桿徑 0.12 m 為示意，燈頭與懸臂尚未核對。'},popupTemplate:{title:'市府號誌設施 {sourceId}',content:'{note}'}}));
