 $('junctionReviewView').onclick=async()=>{if(loading||getPlace()!=='xinyi')return;loading=true;const ticket=sequence;try{const longitude=121.565445,latitude=25.03582,q=await map.ground.queryElevation(new Point({longitude,latitude,spatialReference:{wkid:4326}}));if(ticket!==sequence)return;if(!Number.isFinite(q.geometry.z))throw Error('地形尚未完成');await view.goTo({position:{longitude,latitude,z:q.geometry.z+17},heading:180,tilt:40},{animate:false});}catch(e){if(e.name!=='AbortError')$('fixtureStatus').textContent='路口標線視角未完成，請重試。';}finally{loading=false;}};
 $('waitingReviewView').onclick=async()=>{if(loading||getPlace()!=='xinyi')return;loading=true;const ticket=sequence;try{const longitude=121.565445,latitude=25.03561,q=await map.ground.queryElevation(new Point({longitude,latitude,spatialReference:{wkid:4326}}));if(ticket!==sequence)return;if(!Number.isFinite(q.geometry.z))throw Error('地形高度未完成');await view.goTo({position:{longitude,latitude,z:q.geometry.z+30},heading:0,tilt:30},{animate:false});}catch(e){if(e.name!=='AbortError')$('fixtureStatus').textContent='停等框核對視角未完成，請重試。';}finally{loading=false;}};
 $('paintReviewView').onclick=async()=>{if(loading||getPlace()!=='xinyi')return;for(const id of ['laneReviewVisible','junctionReviewVisible','waitingReviewVisible'])$(id).checked=true;visibility();loading=true;const ticket=sequence;try{const longitude=121.565445,latitude=25.03530,q=await map.ground.queryElevation(new Point({longitude,latitude,spatialReference:{wkid:4326}}));if(ticket!==sequence)return;if(!Number.isFinite(q.geometry.z))throw Error('地形高度未完成');await view.goTo({position:{longitude,latitude,z:q.geometry.z+35},heading:0,tilt:45},{animate:false});}catch(e){if(e.name!=='AbortError')$('fixtureStatus').textContent='標線銜接視角未完成，請重試。';}finally{loading=false;}};
